insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('56099','test','Тест к уроку 4. HR','guru-25811','{"id":"56099","title":"Тест к уроку 4. HR","timeLimitSeconds":300,"passCount":10,"questions":[{"id":"56099-1","text":"Найдите лишний пункт в описании профиля соискателя на должность в ресторане.","type":"single","options":["Пунктуальный","Гостеприимный","Легкий на подъем","Ответственный"],"image":"assets/remaining-tests/bb3f5b91bc4c636f6452beb1.jpg","images":["assets/remaining-tests/bb3f5b91bc4c636f6452beb1.jpg"]},{"id":"56099-2","text":"За сколько времени складывается первое впечатление нового сотрудника о ресторане?","type":"single","options":["10 часов","3,5 часа","2,5 часа","12 часов"],"image":"assets/remaining-tests/d29bfc52bf7ca805b641bd84.jpg","images":["assets/remaining-tests/d29bfc52bf7ca805b641bd84.jpg"]},{"id":"56099-3","text":"Собеседование: Как можно проверить, умеет ли кандидат на должность официанта вкусно рассказывать о еде?","type":"single","options":["Попросить его описать блюдо из вашего меню.","Попросить описать свое любимое блюдо.","Спросить его, умеет ли он вкусно рассказывать о еде."],"image":"assets/remaining-tests/0eb0a993e4e2bb37c7628d26.jpg","images":["assets/remaining-tests/0eb0a993e4e2bb37c7628d26.jpg"]},{"id":"56099-4","text":"Собеседование: Какие дополнительные вопросы вы зададите кандидату на должность \"Официант\",если причина его увольнения с предыдущего места - мало денег. Отметьте НЕПРАВИЛЬНЫЙ вариант","type":"single","options":["А сколько бы вы хотели зарабатывать, точная сумма?","Почему бы вам не поработать над собственной скромностью?","Почему вы думаете, что у нас в ресторане получится зарабатывать столько?","Почему не получилось зарабатывать желаемую сумму денег на предыдущем месте?"],"image":"assets/remaining-tests/93023974f086d2d4e7b815ba.jpg","images":["assets/remaining-tests/93023974f086d2d4e7b815ba.jpg"]},{"id":"56099-5","text":"Какой вы сделаете вывод о соискателе на должность официанта, который пришел на собеседование в грязной футболке?","type":"single","options":["У нас в ресторане есть униформа, поэтому нет никакой разницы в чем человек приходит на собеседование.","Он неаккуратен и не заинтересован в получении этой должности, иначе оделся бы хотя бы в чистое.","Сделаю вывод, что у него финансовые сложности и ему совсем нечего надеть."],"image":"assets/remaining-tests/335bdff9fc5c17e5a0ed34fb.jpg","images":["assets/remaining-tests/335bdff9fc5c17e5a0ed34fb.jpg"]},{"id":"56099-6","text":"Собеседование: Как можно на первом собеседовании составить представление о пунктуальности кандидата.","type":"multiple","options":["Спросить его, почему люди опаздывают. Если он начнет перечислять причины — он часто опаздывает. Если отвечает категорично и с негативной окраской — он пунктуален.","Посмотреть, вовремя ли он пришел на собеседование. Если пришел с опозданием и даже не извинился — человек точно непунктуален.","Спросить кандидата, пунктуальный ли он человек."],"image":"assets/remaining-tests/6cdc47c2b0a8644876136b48.jpg","images":["assets/remaining-tests/6cdc47c2b0a8644876136b48.jpg"]},{"id":"56099-7","text":"Основные три принципа успешной и взаимовыгодной стажировки нового сотрудника в ресторане это:","type":"single","options":["четко прописанная программа со сроками, наставничество и обратная связь.","знание меню, знание барной карты, знание английского языка","пунктуальность, чистоплотность, терпение"],"image":"assets/remaining-tests/c8bdbb790125a06ab777489f.jpg","images":["assets/remaining-tests/c8bdbb790125a06ab777489f.jpg"]},{"id":"56099-8","text":"Какой вы сделаете вывод о соискателе на должность официанта, который пришел на собеседование на полчаса позже заявленного времени и не предупредил об этом заранее?","type":"single","options":["Решу, что он долго искал к нам дорогу. Это уважительная причина.","Он не уважает чужое время. Возьму такого только в самом крайнем случае.","Видимо, у него были другие важные дела. В этом нет ничего страшного, главное - дошел!"],"image":"assets/remaining-tests/c4f331317ebd5e6771d736ac.jpg","images":["assets/remaining-tests/c4f331317ebd5e6771d736ac.jpg"]},{"id":"56099-9","text":"Как часто нужно администратору общаться со стажером один на один?","type":"single","options":["Когда он поступает на стажировку и во время аттестации","Каждый рабочий день стажера","В начале и в конце каждой недели"],"image":"assets/remaining-tests/8664b7bd5bcc75e51939e3f8.jpg","images":["assets/remaining-tests/8664b7bd5bcc75e51939e3f8.jpg"]},{"id":"56099-10","text":"Почему хорошей практикой является спросить соискателя о недавнем позитивном и негативном опыте посещения общепита?","type":"single","options":["Отвечая на эти вопросы он невольно сделает акценты на тех пунктах, на которые он будет обращать внимание в работе.","Из его ответа мы узнаем, как часто он ходит в рестораны и какие предпочитает.","Интересен уровень достатка соискателя, какие заведения общепита он может себе позволить и как часто это делает."],"image":"assets/remaining-tests/e63f955c1badbb3bee41bd59.jpg","images":["assets/remaining-tests/e63f955c1badbb3bee41bd59.jpg"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('56100','test','Тест к уроку 5. Коммуникация на смене и обратная связь.','guru-25811','{"id":"56100","title":"Тест к уроку 5. Коммуникация на смене и обратная связь.","timeLimitSeconds":300,"passCount":10,"questions":[{"id":"56100-1","text":"Как нужно хвалить сотрудника?","type":"single","options":["Своевременно, лично, за его личностные качества, при всех.","Своевременно, лично, за конкретное действие, при всех.","Лично, за конкретное действие, не менее 10 минут, один на один."],"image":"assets/remaining-tests/b4384517063bab6b9745b32a.jpg","images":["assets/remaining-tests/b4384517063bab6b9745b32a.jpg"]},{"id":"56100-2","text":"Какая обратная связь важнее для эффективной работы с персоналом- позитивная или конструктивная?","type":"single","options":["Позитивная","Конструктивная","Обе одинаково важны"],"image":"assets/remaining-tests/b981cb075ed2788a62094ed6.jpg","images":["assets/remaining-tests/b981cb075ed2788a62094ed6.jpg"]},{"id":"56100-3","text":"Какую цель некорректно ставить официанту на встрече по развитию?","type":"single","options":["Цель по личному среднему чеку.","Цель по индивидуальной выручке.","Цель по сбору положительных отзывов от гостей.","Цель по продаже определенного количества фирменных блюд/напитков."],"image":"assets/remaining-tests/f55ca62671a9cddca13e4fd4.jpg","images":["assets/remaining-tests/f55ca62671a9cddca13e4fd4.jpg"]},{"id":"56100-4","text":"Для чего нужны еженедельные встречи с каждым сотрудником?","type":"single","options":["Эти встречи нужны для того, чтобы лишний раз напомнить каждому сотруднику о субординации между менеджерами и рядовыми сотрудниками.","Эти встречи нужны для того, чтобы узнать, как дела у каждого из моих подчиненных, не собирается-ли кто-то из них увольняться.","Это встречи по личному развитию. Они должны мотивировать и воздействовать на лояльность сотрудника. Нужны для обсуждения хода выполнения личных целей, постановки новых."],"image":"assets/remaining-tests/7a43daa0f955ce89028a58f6.jpg","images":["assets/remaining-tests/7a43daa0f955ce89028a58f6.jpg"]},{"id":"56100-5","text":"Какие инструменты нужны вам на каждой встрече с сотрудником?","type":"single","options":["Чеклисты за неделю, отчеты по среднему чеку и выручке, отзывы гостей.","Ведомость заработной платы, отчеты по среднему чеку и выручке, журнал здоровья","Чеклисты за неделю, лист прихода на смену."],"image":"assets/remaining-tests/9b2fa6bc14ebb0808494628f.jpg","images":["assets/remaining-tests/9b2fa6bc14ebb0808494628f.jpg"]},{"id":"56100-6","text":"За сколько времени нужно предупредить сотрудника о месте и времени встречи по развитию?","type":"single","options":["За 1 сутки, предупредить нужно лично, пока человек находится на смене за работой.","За 7 дней, на каждой встрече назначаю даты новой встречи.","За 2 часа, можно написать человеку в месенджер в его выходной день и попросить срочно приехать."],"image":"assets/remaining-tests/1058bf18c779bcc6d9d1b378.jpg","images":["assets/remaining-tests/1058bf18c779bcc6d9d1b378.jpg"]},{"id":"56100-7","text":"Как нужно давать конструктивную критику?","type":"single","options":["Своевременно, личность, но не поступок, при всех.","В конце смены, при всех, на собрании.","Своевременно, поступок, а не личность, один на один."],"image":"assets/remaining-tests/829565ed1c5974ffb69dab86.jpg","images":["assets/remaining-tests/829565ed1c5974ffb69dab86.jpg"]},{"id":"56100-8","text":"Для чего нужно хвалить своих сотрудников?","type":"single","options":["Сотрудников хвалить не нужно, это их расхолаживает.","Потому, что спокойный и счастливый сотрудник - самый эффективный.","Потому что нужно быть добрым и отзывчивым человеком."],"image":"assets/remaining-tests/9263af3420deb7bd3d387946.jpg","images":["assets/remaining-tests/9263af3420deb7bd3d387946.jpg"]},{"id":"56100-9","text":"Для чего на встрече по развитию нужны чеклисты за неделю?","type":"single","options":["Для того, чтобы посмотреть, как часто их заполняют сотрудники на смене.","Для того, чтобы сосчитать количество чеклистов за всю неделю.","Для того, чтобы восстановить картину каждой смены сотрудника и отследить его эффективность."],"image":"assets/remaining-tests/601c8250b11924d764c7ef13.jpg","images":["assets/remaining-tests/601c8250b11924d764c7ef13.jpg"]},{"id":"56100-10","text":"Для чего к встрече по развитию нужно подготовить отзывы гостей за неделю?","type":"single","options":["Отзывы бывают очень забавными - совместное их прочтение разрядит обстановку.","Для того, чтобы показать сотруднику обратную связь от гостей за каждую смену.","Для того, чтобы наказать сотрудника за каждый негативный отзыв гостей."],"image":"assets/remaining-tests/13bf4769fcade601a92c0100.jpg","images":["assets/remaining-tests/13bf4769fcade601a92c0100.jpg"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('56101','test','Тест к уроку 6. Роль менеджера в построении продажи','guru-25811','{"id":"56101","title":"Тест к уроку 6. Роль менеджера в построении продажи","timeLimitSeconds":150,"passCount":5,"questions":[{"id":"56101-1","text":"Как правильно распределить выручку на день?","type":"single","options":["В соотношении - 1/3 утренняя смена, 2/3 вечерняя","Не распределять, пусть вечерняя смена \"добивает\" выручку до нужной суммы","Поровну, 50% на 50%, между утренней и вечерней сменой"],"image":"assets/remaining-tests/e563ebe6979a5f501e64cdeb.jpg","images":["assets/remaining-tests/e563ebe6979a5f501e64cdeb.jpg"]},{"id":"56101-2","text":"Для чего нужно рассчитывать выручку ресторана?","type":"single","options":["Для того чтобы корректно ставить цель по выручке на день/неделю/месяц","Для того чтобы при удобном случае блеснуть своей осведомлённостью в финансовых делах компании","Для того чтобы отчитываться перед руководством"],"image":"assets/remaining-tests/4204159d77b26ab5a70969e2.jpg","images":["assets/remaining-tests/4204159d77b26ab5a70969e2.jpg"]},{"id":"56101-3","text":"Следует ли корректировать индивидуальные цели по продажам?","type":"single","options":["Не следует, цели должны быть одинаковыми, чтобы никому не было обидно","Следует, с учетом навыков продаж каждого сотрудника","Следует, с учетом личного отношения к сотруднику"],"image":"assets/remaining-tests/1ce32a386ab01e8e46a21706.jpg","images":["assets/remaining-tests/1ce32a386ab01e8e46a21706.jpg"]},{"id":"56101-4","text":"Следует ли мотивировать сотрудников на продажи?","type":"single","options":["Да, это одна из важнейших задач менеджера","Нет, каждый сотрудник сам находит мотивацию для работы","Официанты и без мотивации неплохо справятся"],"image":"assets/remaining-tests/36d3d789c10fd2e8bc8020c6.jpg","images":["assets/remaining-tests/36d3d789c10fd2e8bc8020c6.jpg"]},{"id":"56101-5","text":"Для чего нужен чек-лист обслуживания?","type":"single","options":["Это шаги обслуживания, за невыполнение которых администратор должен отругать официанта.","Это инструмент измерения эффективности и повод для обратной связи для каждого официанта.","Это рутинный инструмент, заполнение которого входит в обязанности каждого менеджера смены."],"image":"assets/remaining-tests/9c32f8290fd5fdb70ec5f35e.jpg","images":["assets/remaining-tests/9c32f8290fd5fdb70ec5f35e.jpg"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('56102','test','Тест к уроку 7. Лучшая практика для выполнения плана по продажам','guru-25811','{"id":"56102","title":"Тест к уроку 7. Лучшая практика для выполнения плана по продажам","timeLimitSeconds":180,"passCount":6,"questions":[{"id":"56102-1","text":"Как часто нужно напоминать сотрудникам о ходе проведения конкурса?","type":"single","options":["Каждый день на пятиминутке.","Каждую неделю на встрече по развитию.","Каждый месяц на собрании."],"image":"assets/remaining-tests/be7931abb0664f519929694f.jpg","images":["assets/remaining-tests/be7931abb0664f519929694f.jpg"]},{"id":"56102-2","text":"Конкурсы: Продолжите фразу: Награждать за победу в конкурсе нужно...","type":"single","options":["тихо, один на один, в кабинете администратора. Нам ни к чему зависть и расстройство других сотрудников.","публично и с большим охватом. Это вы делаете, чтобы каждый хотел оказаться в следующий раз на месте победителя."],"image":"assets/remaining-tests/a1d29d306d70583e605eccea.jpg","images":["assets/remaining-tests/a1d29d306d70583e605eccea.jpg"]},{"id":"56102-3","text":"Отметьте вариант, который не является одним из шагов проведения конкурсов в ресторане.","type":"single","options":["Определить тему конкурса.","Отчитать неуспевающих.","Придать конкурс огласке среди сотрудников.","Определить время старта и окончания."],"image":"assets/remaining-tests/6868d851d3150583c69a567b.jpg","images":["assets/remaining-tests/6868d851d3150583c69a567b.jpg"]},{"id":"56102-4","text":"Почему важно четко определить время старта и время окончания конкурса?","type":"single","options":["Нарушение этих сроков плохо повлияет на вашу репутацию управленца.","Для того, чтобы уложиться в месячный план по выручке.","Для того, чтобы выполнить план по продвижению сезонного меню."],"image":"assets/remaining-tests/f7d4ccac31704d7d2e697ca6.jpg","images":["assets/remaining-tests/f7d4ccac31704d7d2e697ca6.jpg"]},{"id":"56102-5","text":"Самые популярные цели проведения конкурсов по продажам это:","type":"multiple","options":["Увеличение продаж на дополнительных предложениях.","Выявление самых простых для продажи блюд в ресторане.","Увеличение продаж определенных напитков или блюд."],"image":"assets/remaining-tests/682a8b78b7212e864aaf937f.jpg","images":["assets/remaining-tests/682a8b78b7212e864aaf937f.jpg"]},{"id":"56102-6","text":"Конкурсы: Инструкция по запуску. Выберите лишний пункт из инструкции:","type":"single","options":["Определить мотивирующий приз.","Сделать так, чтобы победитель выявился уже в первые дни конкурса.","Определить тему конкурса, время старта и окончания.","Сделать мотивационную доску конкурса и придать огласке результаты."],"image":"assets/remaining-tests/02737463463236db6b4e9f75.jpg","images":["assets/remaining-tests/02737463463236db6b4e9f75.jpg"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('56103','test','Тест к уроку 8. Постановка целей.','guru-25811','{"id":"56103","title":"Тест к уроку 8. Постановка целей.","timeLimitSeconds":150,"passCount":5,"questions":[{"id":"56103-1","text":"Почему цель должна иметь временные рамки?","type":"single","options":["Потому, что у менеджера нет лишнего времени.","Потому, что ограничение по времени позволяет гораздо проще отчитываться перед своим руководством.","Временное ограничение помогает сосредоточиться на достижении цели в установленный срок или раньше."],"image":"assets/remaining-tests/b9ed6fe52d3deca10295390c.jpg","images":["assets/remaining-tests/b9ed6fe52d3deca10295390c.jpg"]},{"id":"56103-2","text":"Что такое SMART?","type":"multiple","options":["Это эффективный метод постановки целей.","это аббревиатура, образованная первыми буквами английских слов, в переводе на русский язык обозначающая «умный».","сокращение от \"Смартфон\"."],"image":"assets/remaining-tests/7fb498791ebca2d6a6483228.jpg","images":["assets/remaining-tests/7fb498791ebca2d6a6483228.jpg"]},{"id":"56103-3","text":"Что может произойти, если цель будет поставлена некорректно?","type":"single","options":["Она не будет понята, не будет мотивировать, соответственно, не будет выполнена.","Ее выполнит другой сотрудник."],"image":"assets/remaining-tests/3512620e8995e0d105a0e073.jpg","images":["assets/remaining-tests/3512620e8995e0d105a0e073.jpg"]},{"id":"56103-4","text":"Для чего нужно ставить сотрудникам цели по SMART? Отметьте все верные ответы:","type":"multiple","options":["Чтобы они лучше понимали, что от них требуется.","Чем конкретнее и понятнее цель, тем больше шансов, что она будет выполнена.","Чтобы замотивировать их к выполнению этой цели."],"image":"assets/remaining-tests/35d1d043e2da27663dfed9d3.jpg","images":["assets/remaining-tests/35d1d043e2da27663dfed9d3.jpg"]},{"id":"56103-5","text":"Как понять, что цель измерима?","type":"single","options":["Можно измерить, насколько эта цель полезна для вашего ресторана.","Можно измерить, за сколько времени эта цель может быть выполнена.","Можно ответить на вопрос \"Что будет результатом? Как я пойму, что цель достигнута?\""],"image":"assets/remaining-tests/2fbcae9363f145531815a4dd.jpg","images":["assets/remaining-tests/2fbcae9363f145531815a4dd.jpg"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('95471','test','Тест "Гостеприимство, продажи и средний чек"','guru-44662','{"id":"95471","title":"Тест \"Гостеприимство, продажи и средний чек\"","timeLimitSeconds":300,"passCount":10,"questions":[{"id":"95471-1","text":"Выберите вариант предложения закусок, который сработает эффективнее всего:","type":"single","options":["Не хотите чего-нибудь на закуску?","На закуску рекомендую антипасти - это всё богатство Италии в одном блюде - панчетта, брезаола, сыры пармезан и пекорино, маслины, артишоки и гриссини.","Что желаете на закуску?"],"image":"assets/remaining-tests/b928a7cacd459aa7eceed5f9.jpg","images":["assets/remaining-tests/b928a7cacd459aa7eceed5f9.jpg"]},{"id":"95471-2","text":"Зачем нужно знать технологию приготовления каждого блюда?","type":"single","options":["Для того, чтобы максимально красочно создать в голове гостя образ этого блюда.","Чтобы можно было приготовить его дома.","Не нужно знать технологию, достаточно знать состав."],"image":"assets/remaining-tests/0c9d9f08473814cb702b90be.jpg","images":["assets/remaining-tests/0c9d9f08473814cb702b90be.jpg"]},{"id":"95471-3","text":"Выберите вариант предложения напитков, который сработает эффективнее всего:","type":"single","options":["Что желаете из напитков?","Что принести из напитков? Минеральную воду или сок?","Что-нибудь пить будете?"],"image":"assets/remaining-tests/28961c48dca33d47eefe4272.jpg","images":["assets/remaining-tests/28961c48dca33d47eefe4272.jpg"]},{"id":"95471-4","text":"Дополнительные продажи в ресторане могут работать только на \"избранных\", особо \"хороших столиках\", например, для компании дорого одетых мужчин, настроенных выпить. Для других столиков, например, для женских компаний, можно даже не пытаться делать дополнительные продажи. Это утверждение правдиво?","type":"single","options":["Правдиво.","Не правдиво."],"image":"assets/remaining-tests/594275c25ebc69e7d5ea2da1.jpg","images":["assets/remaining-tests/594275c25ebc69e7d5ea2da1.jpg"]},{"id":"95471-5","text":"Чтобы понять, как именно лучше общаться с гостем, эффективнее всего будет...","type":"single","options":["Общаться одинаково, учтиво и отстраненно со всеми гостями.","Общаться сразу подчеркнуто вежливо и заискивающе.","Поставить себя на его место."],"image":"assets/remaining-tests/34fd684044283a3e9161da81.jpg","images":["assets/remaining-tests/34fd684044283a3e9161da81.jpg"]},{"id":"95471-6","text":"Выберите вариант дополнительного предложения, который сработает эффективнее всего:","type":"single","options":["Хотите трюфель к кофе? Их каждый день готовят в нашей кондитерской из бельгийского темного шоколада с коньяком","Может быть, что-нибудь еще?","Что-нибудь к чаю, пирожное, например?"],"image":"assets/remaining-tests/81eaa91019aea973963f63c1.jpg","images":["assets/remaining-tests/81eaa91019aea973963f63c1.jpg"]},{"id":"95471-7","text":"Выберите вариант предложения напитков, который сработает эффективнее всего:","type":"single","options":["Что-нибудь принести на аперитив?","Что предпочтете на аперитив? Игристое вино или джин-тоник?","Не хотите ли шампанского?"],"image":"assets/remaining-tests/04d97feab02509ff434db7bd.jpg","images":["assets/remaining-tests/04d97feab02509ff434db7bd.jpg"]},{"id":"95471-8","text":"Что можно дополнительно предложить к чаю?","type":"multiple","options":["Лимон","Мед","Чабрец","Мята","Лёд"],"image":"assets/remaining-tests/f178c64c901a7a17de463fa8.jpg","images":["assets/remaining-tests/f178c64c901a7a17de463fa8.jpg"]},{"id":"95471-9","text":"Что можно дополнительно предложить к кофе?","type":"multiple","options":["Сахар","Мини-десерт","Сливки","Сироп","Молоко"],"image":"assets/remaining-tests/b801697c37d7ccf67a4dffe8.jpg","images":["assets/remaining-tests/b801697c37d7ccf67a4dffe8.jpg"]},{"id":"95471-10","text":"На вопрос гостя «Что у вас сегодня самое вкусное?» следует отвечать:","type":"single","options":["Предложить на выбор фирменные блюда или блюда «от шеф-повара»;","«У нас всё вкусное, выбирайте»;","«Это зависит от ваших вкусов, я же не знаю, что вы любите»."],"image":"assets/remaining-tests/8a5f8f795a78349a92bee05b.jpg","images":["assets/remaining-tests/8a5f8f795a78349a92bee05b.jpg"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('55942','test','Тест "Приветствие гостей"','guru-25724','{"id":"55942","title":"Тест \"Приветствие гостей\"","timeLimitSeconds":240,"passCount":8,"questions":[{"id":"55942-1","text":"Как сообщить гостю, что свободных столиков в данный момент нет?","type":"multiple","options":["No table for you sir.","I’m sorry. The restaurant is full now.","We don’t have available table at the moment.","You can’t sit."],"image":"assets/remaining-tests/18af09e6d3a6d08a0eea03dd.jpg","images":["assets/remaining-tests/18af09e6d3a6d08a0eea03dd.jpg"]},{"id":"55942-2","text":"Как спросить у гостя, подходит ли ему предложенный столик?","type":"single","options":["Do you want this table?","Is this table yours?","Will this table be all right?"],"image":"assets/remaining-tests/171ae3cb49006de74a9a275b.jpg","images":["assets/remaining-tests/171ae3cb49006de74a9a275b.jpg"]},{"id":"55942-3","text":"Фраза Do you have a reservation? переводится как","type":"single","options":["На ваше имя нет брони.","Вы бронировали столик?","Вы хотите забронировать столик?"],"image":"assets/remaining-tests/c35f4c7c395fc20cf251912a.jpg","images":["assets/remaining-tests/c35f4c7c395fc20cf251912a.jpg"]},{"id":"55942-4","text":"Что вы можете сказать, когда приветствуете гостя?","type":"multiple","options":["Hello!","Good morning!","Bye!","Good Day!"],"image":"assets/remaining-tests/11486ee60ddb510dc42afa8c.jpg","images":["assets/remaining-tests/11486ee60ddb510dc42afa8c.jpg"]},{"id":"55942-5","text":"Как предупредить гостя, что в ресторане не курят?","type":"multiple","options":["You can’t smoke in the restaurant.","There is no smoking in the restaurant.","Sorry, no smoking."],"image":"assets/remaining-tests/f42d161017f894ed3a376109.jpg","images":["assets/remaining-tests/f42d161017f894ed3a376109.jpg"]},{"id":"55942-6","text":"Что можно сказать гостю, когда он сел за стол?","type":"multiple","options":["The menus are there.","Enjoy your evening.","Have a good day sir/madam.","Here are your menus."],"image":"assets/remaining-tests/7980de65838af1c31ef718b9.jpg","images":["assets/remaining-tests/7980de65838af1c31ef718b9.jpg"]},{"id":"55942-7","text":"Как можно спросить о количестве гостей в компании?","type":"multiple","options":["How many people?","Chair for 2?","Party of 2?","Table for 2?"],"image":"assets/remaining-tests/a6ab0f43872bb5488a0b4eee.jpg","images":["assets/remaining-tests/a6ab0f43872bb5488a0b4eee.jpg"]},{"id":"55942-8","text":"Как спросить у гостя, хочет ли он подождать, пока освободится столик?","type":"multiple","options":["Will you wait?","Do you want to wait?","Would you like to wait?","Wait here."],"image":"assets/remaining-tests/9e629bab29ce50714437e26a.jpg","images":["assets/remaining-tests/9e629bab29ce50714437e26a.jpg"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('55943','test','Тест "Прием заказа"','guru-25724','{"id":"55943","title":"Тест \"Прием заказа\"","timeLimitSeconds":270,"passCount":9,"questions":[{"id":"55943-1","text":"Какие слова можно использовать, чтобы показать гостю, что вы его поняли?","type":"multiple","options":["Great","Cool","Nope","Well","Alright","OK"],"image":"assets/remaining-tests/517e165ea5791137a7865f69.jpg","images":["assets/remaining-tests/517e165ea5791137a7865f69.jpg"]},{"id":"55943-2","text":"Какую фразу вы скажете, если хотите повторить заказ?","type":"multiple","options":["So your order is..","Here you are.","Let me repeat your order.","Listen to me."],"image":"assets/remaining-tests/e9d538f7d79b37efb86dcf6b.jpg","images":["assets/remaining-tests/e9d538f7d79b37efb86dcf6b.jpg"]},{"id":"55943-3","text":"Как спросить гостя о желаемой степени прожарки стейка?","type":"single","options":["How would you like your steak done?","How would you do your steak?","Do you want to cook steak?"],"image":"assets/remaining-tests/47d615a7089e28ae26d24c6e.jpg","images":["assets/remaining-tests/47d615a7089e28ae26d24c6e.jpg"]},{"id":"55943-4","text":"Какие фразы можно использовать, когда вы представляетесь гостю ресторана?","type":"multiple","options":["Hello, my name is Michael.","I will be your server today.","Please give me your menus.","Good evening. What is your name?"],"image":"assets/remaining-tests/30fbcbd7c9c86d3849ebf754.jpg","images":["assets/remaining-tests/30fbcbd7c9c86d3849ebf754.jpg"]},{"id":"55943-5","text":"Что не является названием гарнира?","type":"multiple","options":["Grilled salmon","Mushroom soup","White rice","Steamed vegetables","Green salad","French fries"],"image":"assets/remaining-tests/0cd6b13c743151d2e6437e5c.jpg","images":["assets/remaining-tests/0cd6b13c743151d2e6437e5c.jpg"]},{"id":"55943-6","text":"Что такое side dish по-русски?","type":"single","options":["Соус","Закуска","Основное блюдо","Гарнир"],"image":"assets/remaining-tests/d6326f74d97b724f6090016e.jpg","images":["assets/remaining-tests/d6326f74d97b724f6090016e.jpg"]},{"id":"55943-7","text":"Что можно спросить у гостя, когда принимаете заказ?","type":"multiple","options":["May I take your order?","Who ordered this?","Where is your order?","Are you ready to order?"],"image":"assets/remaining-tests/3162aea212bff65b8d7afe20.jpg","images":["assets/remaining-tests/3162aea212bff65b8d7afe20.jpg"]},{"id":"55943-8","text":"Как принять заказ напитков?","type":"multiple","options":["Do you would drinks?","Anything to drink?","Would you like to order drinks?","Order drinks!"],"image":"assets/remaining-tests/93e8cba6433ad39d4cb555e2.jpg","images":["assets/remaining-tests/93e8cba6433ad39d4cb555e2.jpg"]},{"id":"55943-9","text":"Если гость хочет заказать газированную воду с лимоном, но без льда, то он скажет","type":"single","options":["Still water with lemon but without ice.","Sparkling water with lemon, no ice.","Sparkling water with ice, no lemon.","Still water without lemon or ice."],"image":"assets/remaining-tests/7b1e10441374e6ea66c0c241.jpg","images":["assets/remaining-tests/7b1e10441374e6ea66c0c241.jpg"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('55944','test','Тест "Общение во время ужина"','guru-25724','{"id":"55944","title":"Тест \"Общение во время ужина\"","timeLimitSeconds":300,"passCount":10,"questions":[{"id":"55944-1","text":"Какую из этих фраз не стоит говорить, когда подаёте заказ?","type":"single","options":["Here you are.","Here is your steak.","This is not your steak."],"image":"assets/remaining-tests/e10f9511c193fb3da48252b2.jpg","images":["assets/remaining-tests/e10f9511c193fb3da48252b2.jpg"]},{"id":"55944-2","text":"Как уточнить у гостя, закончил ли он есть?","type":"multiple","options":["Do you want to eat?","Could you take your plate?","Can I take your plate?","Are you finished?"],"image":"assets/remaining-tests/cce47b42e21612fb1ee1be4e.jpg","images":["assets/remaining-tests/cce47b42e21612fb1ee1be4e.jpg"]},{"id":"55944-3","text":"Как уточнить у гостя, хочет ли он повторить заказ напитка?","type":"multiple","options":["How is your drink?","Do you want another water?","Would you like a refill?","Is your drink OK?"],"image":"assets/remaining-tests/c0ea66cffc15cb2724f39853.jpg","images":["assets/remaining-tests/c0ea66cffc15cb2724f39853.jpg"]},{"id":"55944-4","text":"Выберите слова, обозначающие вкусы мороженного.","type":"multiple","options":["Chocolate.","Vanilla.","Strawberry.","Salty.","Green.","Potato."],"image":"assets/remaining-tests/85279ef86a7807803d47fa1a.jpg","images":["assets/remaining-tests/85279ef86a7807803d47fa1a.jpg"]},{"id":"55944-5","text":"Как спросить у гостя, нужно ли ему ещё что-нибудь?","type":"multiple","options":["Would you like anything else?","Nothing else?","Do you have anything else?","Anything else?"],"image":"assets/remaining-tests/fa3c748a9beacfbafa284c50.jpg","images":["assets/remaining-tests/fa3c748a9beacfbafa284c50.jpg"]},{"id":"55944-6","text":"Как пожелать гостю приятного аппетита?","type":"multiple","options":["Don’t eat your meal!","Eat your food!","Enjoy!","Enjoy your meal!"],"image":"assets/remaining-tests/3ed46cd017f1c28ab2fdef21.jpg","images":["assets/remaining-tests/3ed46cd017f1c28ab2fdef21.jpg"]},{"id":"55944-7","text":"Что вы можете сказать, если гость попросил меню с десертами?","type":"multiple","options":["Where is our dessert menu?","Here is our dessert menu.","I’ll bring you our dessert menu.","I don’t want a dessert."],"image":"assets/remaining-tests/b736802c1541362ab81d49d1.jpg","images":["assets/remaining-tests/b736802c1541362ab81d49d1.jpg"]},{"id":"55944-8","text":"Как спросить у гостя, нравится ли ему еда?","type":"multiple","options":["Where is your food?","Is everything OK?","Where is your food?","Is everything bad?","Who is your food?","How is your food?"],"image":"assets/remaining-tests/424a69823297acfa00558045.jpg","images":["assets/remaining-tests/424a69823297acfa00558045.jpg"]},{"id":"55944-9","text":"Какую фразу вы скажите гостю, чтобы предложить десерт?","type":"multiple","options":["Here is your dessert.","Did you eat a dessert?","Would you like a dessert?","How about a dessert?"],"image":"assets/remaining-tests/b17076ec7e66d5c5dcab7267.jpg","images":["assets/remaining-tests/b17076ec7e66d5c5dcab7267.jpg"]},{"id":"55944-10","text":"Как перевести фразу гостя “Can I have some more napkins please?”?","type":"single","options":["Кому нужны ещё салфетки?","Можно мне другие приборы?","Можно мне другую тарелку?","Можно мне ещё салфеток?"],"image":"assets/remaining-tests/e6230931f0902cd3472fff2c.jpg","images":["assets/remaining-tests/e6230931f0902cd3472fff2c.jpg"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('55945','test','Тест "Рекомендации и обсуждение меню"','guru-25724','{"id":"55945","title":"Тест \"Рекомендации и обсуждение меню\"","timeLimitSeconds":180,"passCount":6,"questions":[{"id":"55945-1","text":"Какие из этих слов НЕ являются английскими названиями морепродуктов?","type":"multiple","options":["Pork","Salmon","Clams","Shrimps","Tomato","Beef","Chicken"],"image":"assets/remaining-tests/6c195d62e2579f8cabc8b0e3.jpg","images":["assets/remaining-tests/6c195d62e2579f8cabc8b0e3.jpg"]},{"id":"55945-2","text":"Как сказать «вкусный» по-английски?","type":"single","options":["Awful","Bad","Delicious","Nice"],"image":"assets/remaining-tests/39fc9c2392b15796501ebce5.jpg","images":["assets/remaining-tests/39fc9c2392b15796501ebce5.jpg"]},{"id":"55945-3","text":"Какие из этих фраз вы можете использовать, чтобы порекомендовать гостю то или иное блюдо?","type":"multiple","options":["I wouldn’t recommend the Caesar salad.","Try the Caesar salad.","I would recommend the Caesar salad.","Make the Caesar salad."],"image":"assets/remaining-tests/1166007048806db3ab1bd4d5.jpg","images":["assets/remaining-tests/1166007048806db3ab1bd4d5.jpg"]},{"id":"55945-4","text":"Какое из этих слов НЕ обозначается способ приготовления?","type":"single","options":["Boiled","Pan-fried","Caught","Steamed","Grilled"],"image":"assets/remaining-tests/a741d17fa02ff81cbc771e84.jpg","images":["assets/remaining-tests/a741d17fa02ff81cbc771e84.jpg"]},{"id":"55945-5","text":"Как объяснить то, что блюдо подаётся с определённым гарниром?","type":"single","options":["The steak needs garden salad.","You want garden salad with your steak.","The steak comes with garden salad."],"image":"assets/remaining-tests/8d9d6efd4edf48375671a44a.jpg","images":["assets/remaining-tests/8d9d6efd4edf48375671a44a.jpg"]},{"id":"55945-6","text":"Какие из этих вопросов может задать гость о блюде?","type":"multiple","options